UPDATE "programmes" SET "i18n" = '{"bn":{"name":"প্লে গ্রুপ","ageLabel":"1.5 থেকে 2.5 বছর","tagline":"বাড়ির বাইরে প্রথম পা","description":"স্কুল জীবনের একটা নরম শুরু। খেলা, গান, গল্প আর সহজ রুটিনের মধ্যে দিয়ে শিশুরা ধীরে ধীরে মানিয়ে নেয়, আর প্রতি মুহূর্তে পাশে থাকেন একজন শিক্ষিকা।","highlights":["শুরুর দিনগুলোয় অভিভাবক কাছেই থাকেন","ছুঁয়ে, মেখে, নেড়েচেড়ে খেলা","ছড়া, গান আর নাচ","নিজে খাওয়া ও টয়লেটের অভ্যাস"]},"hi":{"name":"प्ले ग्रुप","ageLabel":"1.5 से 2.5 साल","tagline":"घर से बाहर पहला कदम","description":"स्कूल की एक नरम शुरुआत। खेल, गीत, कहानियों और आसान दिनचर्या के बीच बच्चे धीरे-धीरे घुलते-मिलते हैं, और हर पल एक शिक्षिका उनके पास रहती हैं।","highlights":["शुरुआती दिनों में अभिभावक पास ही रहते हैं","छूकर, मलकर, टटोलकर खेलना","कविता, गीत और नाच","खुद खाना और टॉयलेट की आदत"]}}'::jsonb WHERE "slug" = 'play-group' AND "i18n" = '{}'::jsonb;
