UPDATE "programmes" SET "i18n" = '{"bn":{"name":"নার্সারি","ageLabel":"2.5 থেকে 3.5 বছর","tagline":"কৌতূহলী হাত, ব্যস্ত মন","description":"শিশুরা ছোট দলে কাজ করতে শেখে, পুরো বাক্যে কথা বলে আর ক্রেয়ন ধরে নিজের মতো আঁকে। শেখা হয় হাতে-কলমে: বাছাই করা, মেলানো, গড়া আর অভিনয় করে খেলা।","highlights":["ইংরেজি ও বাংলায় কথা বলা","লেখার আগের দাগ টানা","রং, আকার আর 20 পর্যন্ত গোনা","আঁকা, হাতের কাজ আর মাটির কাজ"]},"hi":{"name":"नर्सरी","ageLabel":"2.5 से 3.5 साल","tagline":"जिज्ञासु हाथ, व्यस्त मन","description":"बच्चे छोटे समूह में काम करना सीखते हैं, पूरे वाक्यों में बोलते हैं और क्रेयॉन पकड़कर अपने मन से बनाते हैं। सीखना हाथों से होता है: छाँटना, मिलाना, बनाना और नाटक करके खेलना।","highlights":["अंग्रेज़ी और बांग्ला में बोलना","लिखने से पहले की रेखाएँ","रंग, आकार और 20 तक गिनती","चित्रकला, क्राफ्ट और मिट्टी का काम"]}}'::jsonb WHERE "slug" = 'nursery' AND "i18n" = '{}'::jsonb;
--> statement-breakpoint
UPDATE "programmes" SET "i18n" = '{"bn":{"name":"এলকেজি","ageLabel":"3.5 থেকে 4.5 বছর","tagline":"অক্ষর, সংখ্যা আর আত্মবিশ্বাস","description":"ফোনিক্স, সংখ্যার খেলা আর নিয়মিত অভ্যাসের মধ্যে দিয়ে পড়া ও অঙ্কের কাজ ভালোভাবে শুরু হয়। শিশুরা নিজের কথা বলতে, পালা করে কাজ করতে আর শুরু করা কাজ শেষ করতে শেখে।","highlights":["ফোনিক্স ও প্রথম শব্দ","50 পর্যন্ত সংখ্যা ও সহজ যোগ","অক্ষর ও সংখ্যা লেখা","সবার সামনে বলা ও মঞ্চে ওঠা"]},"hi":{"name":"एलकेजी","ageLabel":"3.5 से 4.5 साल","tagline":"अक्षर, अंक और आत्मविश्वास","description":"फोनिक्स, अंकों के खेल और नियमित अभ्यास से पढ़ने और गिनती का काम ठीक से शुरू होता है। बच्चे अपनी बात कहना, बारी का इंतज़ार करना और शुरू किया काम पूरा करना सीखते हैं।","highlights":["फोनिक्स और पहले शब्द","50 तक अंक और आसान जोड़","अक्षर और अंक लिखना","सबके सामने बोलना और मंच पर आना"]}}'::jsonb WHERE "slug" = 'lkg' AND "i18n" = '{}'::jsonb;
