UPDATE "programmes" SET "i18n" = '{"bn":{"name":"ইউকেজি","ageLabel":"4.5 থেকে 5.5 বছর","tagline":"বড় স্কুলের জন্য তৈরি","description":"এই বছরটা শিশুকে প্রথম শ্রেণির জন্য তৈরি করে: ছোট বাক্য পড়া, পরিষ্কার করে লেখা, সংখ্যা নিয়ে কাজ করা আর পুরো ক্লাস মন দিয়ে বসা। খেলার আনন্দ তাতে একটুও কমে না।","highlights":["বাক্য ও ছোট গল্প পড়া","যোগ, বিয়োগ ও সংখ্যার নাম","ইংরেজি ও বাংলায় পরিষ্কার হাতের লেখা","স্কুলের ইন্টারভিউয়ের প্রস্তুতি"]},"hi":{"name":"यूकेजी","ageLabel":"4.5 से 5.5 साल","tagline":"बड़े स्कूल के लिए तैयार","description":"यह साल बच्चे को पहली कक्षा के लिए तैयार करता है: छोटे वाक्य पढ़ना, साफ़ लिखना, अंकों के साथ काम करना और पूरी कक्षा ध्यान से बैठना। खेलने का आनंद इसमें ज़रा भी कम नहीं होता।","highlights":["वाक्य और छोटी कहानियाँ पढ़ना","जोड़, घटाव और अंकों के नाम","अंग्रेज़ी और बांग्ला में साफ़ लिखावट","स्कूल इंटरव्यू की तैयारी"]}}'::jsonb WHERE "slug" = 'ukg' AND "i18n" = '{}'::jsonb;
